255	  private async turn(): Promise<boolean> {
256	    if (this.phase.kind !== 'running') {
257	      this.throwError(new Error(`agent "${this.id}": turn without driver reservation`))
258	    }
259	    const phase = this.phase
260	    const { signal } = phase.abort
261	    signal.throwIfAborted()
262	    const turn = phase.turn + 1
263	    try {
264	      this.session.append('turn/start', { turn })
265	    } catch (error: unknown) {
266	      this.throwError(error)
267	    }
268	    phase.turn = turn
269	    let turnEnds: TurnEndReason | null = null
270	    let target: InboxTarget = 'next-turn'
271	    try {
272	      while (true) {
273	        signal.throwIfAborted()
274	        const step = phase.step + 1
275	        const decision = await this.preStep(target, { turn, step })
276	        if (decision.kind === 'reject') {
277	          turnEnds = { kind: 'blocked' }
278	          return false
279	        }
280	        if (turnEnds && decision.messages.length === 0) break
281	        // A removed waking message or an enter decision rewritten to empty
282	        // still owns the initial turn boundary, but it spends no model call.
283	        if (phase.step === 0 && decision.messages.length === 0) {
284	          turnEnds = { kind: 'completed' }
285	          return false
286	        }
287	        signal.throwIfAborted()
288	        this.session.append('step/start', { turn, step })
289	        phase.step = step
290	        try {
291	          for (const message of decision.messages) {
292	            this.session.append('user/message', message, { surfaceOp: 'append' })
293	          }
294	          // max-tokens is sticky: once any step hits the ceiling, later steps
295	          // that complete normally must not downgrade the turn outcome.
296	          const stepEnd = await this.step(decision.assembly, decision.startsRequestSeries === true)
297	          // max-tokens stays sticky: a later completed step must not
298	          // downgrade the turn outcome.
299	          if (turnEnds === null || turnEnds.kind !== 'max-tokens') turnEnds = stepEnd
300	        } finally {
301	          this.session.append('step/end', { turn, step })
302	        }
303	        signal.throwIfAborted()
304	        if (turnEnds && this.inbox.nextStep.length === 0) {
305	          await this.dispatch.serial('agent/turn-stopping', { turn, signal })
306	          signal.throwIfAborted()
307	        }
308	        if (turnEnds && this.inbox.nextStep.length === 0) break
309	        target = 'next-step'
310	      }
311	    } catch (error: unknown) {
312	      if (signal.aborted) {
313	        turnEnds = { kind: 'aborted', reason: signal.reason as AgentCancelCause }
314	        throw error
315	      }
316	      // Every failure is structured: an `LlmError` keeps its facts, anything
317	      // else flattens to `errorChain` text under the `UNKNOWN` code.
318	      turnEnds = {
319	        kind: 'error',
320	        error: error instanceof LlmError
321	          ? error.failure
322	          : { message: errorChain(error), code: 'UNKNOWN' },
323	      }
324	      this.throwError(error)
325	    } finally {
326	      try {
327	        // oxlint-disable-next-line typescript/no-non-null-assertion -- every exit assigns a turn ending
328	        this.session.append('turn/end', { turn, reason: turnEnds! })
329	      } catch (error: unknown) {
330	        this.throwError(error)
331	      }
332	    }
333	    if (!this.inbox.hasPending) return false
334	    phase.abort = new AbortController()
